ee:message.ee:set-payload:
%dw 2.0
output application/json
var sla = readUrl("classpath://sla.json", "application/json")
var nowTs = now()
---
payload map ((r) -> do {
    var lastUtc = ((r.LAST_COMMIT as LocalDateTime) as String {format: "yyyy-MM-dd'T'HH:mm:ss"} ++ "Z") as DateTime
    var lag = ((nowTs as Number {unit: "seconds"}) - (lastUtc as Number {unit: "seconds"})) / 60
    var slaMin = sla.tables[r.TABNAME] default sla.defaultMinutes
    ---
    {
        table: r.TABNAME,
        lastCommit: r.LAST_COMMIT,
        lagMinutes: lag as String {format: "0.0"} as Number,
        slaMinutes: slaMin,
        status: if (lag <= slaMin) "OK" else "BREACH"
    }
})
